#!/usr/bin/env node
// Creates all new frontend files for the Admin Module.
// Run from the project root: interview-coach-ai-main/
// Safe to re-run — writes are idempotent (same content = no-op).
import fs from 'fs';
import path from 'path';

const files = {
  "src/services/adminApi.js": "import axios from 'axios';\nimport toast from 'react-hot-toast';\n\n// ─────────────────────────────────────────────────────────────────────────────\n// Separate axios instance for the admin/staff portal. Deliberately NOT the\n// same `API` instance the student app uses in src/services/api.js: it must\n// never attach a student token to an admin request (or vice versa), and a\n// 401 here must only ever clear the admin session, never the student one.\n// ─────────────────────────────────────────────────────────────────────────────\n\nconst ADMIN_API = axios.create({\n  baseURL: import.meta.env.VITE_API_BASE_URL || 'http://localhost:5000/api',\n  timeout: 30000,\n  headers: { 'Content-Type': 'application/json' },\n});\n\nADMIN_API.interceptors.request.use((config) => {\n  const token = localStorage.getItem('adminToken');\n  if (token) config.headers.Authorization = `Bearer ${token}`;\n  return config;\n});\n\nADMIN_API.interceptors.response.use(\n  (response) => response,\n  (error) => {\n    const message = error.response?.data?.message || error.message || 'Something went wrong';\n    if (error.response?.status === 401) {\n      localStorage.removeItem('adminToken');\n      localStorage.removeItem('adminUser');\n      window.location.href = '/staff-login';\n      toast.error('Session expired. Please login again.');\n    } else if (error.response?.status >= 500) {\n      toast.error('Server error. Please try again later.');\n    }\n    return Promise.reject(error);\n  }\n);\n\nexport const adminAuthAPI = {\n  login: (data) => ADMIN_API.post('/admin-auth/login', data),\n  getProfile: () => ADMIN_API.get('/admin-auth/profile'),\n};\n\nexport const adminAPI = {\n  getDashboard: () => ADMIN_API.get('/admin/dashboard'),\n\n  listStudents: (search = '') => ADMIN_API.get('/admin/students', { params: { search } }),\n  getStudent: (id) => ADMIN_API.get(`/admin/students/${id}`),\n  deactivateStudent: (id) => ADMIN_API.put(`/admin/students/${id}/deactivate`),\n  reactivateStudent: (id) => ADMIN_API.put(`/admin/students/${id}/reactivate`),\n  exportStudentsCsv: () => ADMIN_API.get('/admin/students/export', { responseType: 'blob' }),\n\n  listQuestions: (filters = {}) => ADMIN_API.get('/admin/questions', { params: filters }),\n  createQuestion: (data) => ADMIN_API.post('/admin/questions', data),\n  updateQuestion: (id, data) => ADMIN_API.put(`/admin/questions/${id}`, data),\n  activateQuestion: (id) => ADMIN_API.put(`/admin/questions/${id}/activate`),\n  deactivateQuestion: (id) => ADMIN_API.put(`/admin/questions/${id}/deactivate`),\n\n  listStaff: () => ADMIN_API.get('/admin/staff'),\n  createStaff: (data) => ADMIN_API.post('/admin/staff', data),\n  deactivateStaff: (id) => ADMIN_API.put(`/admin/staff/${id}/deactivate`),\n  reactivateStaff: (id) => ADMIN_API.put(`/admin/staff/${id}/reactivate`),\n\n  listEvaluations: (limit = 50) => ADMIN_API.get('/admin/evaluations', { params: { limit } }),\n\n  getAnalytics: () => ADMIN_API.get('/admin/analytics'),\n\n  getEvaluationSettings: () => ADMIN_API.get('/admin/settings/evaluation'),\n  updateEvaluationSettings: (data) => ADMIN_API.put('/admin/settings/evaluation', data),\n  getInterviewSettings: () => ADMIN_API.get('/admin/settings/interview'),\n  updateInterviewSettings: (data) => ADMIN_API.put('/admin/settings/interview', data),\n\n  listNotifications: () => ADMIN_API.get('/admin/notifications'),\n  markNotificationRead: (id) => ADMIN_API.put(`/admin/notifications/${id}/read`),\n  markAllNotificationsRead: () => ADMIN_API.put('/admin/notifications/read-all'),\n\n  getAlerts: () => ADMIN_API.get('/admin/alerts'),\n\n  getAuditLog: () => ADMIN_API.get('/admin/audit-log'),\n};\n\nexport default ADMIN_API;\n",
  "src/context/AdminAuthContext.jsx": "import { createContext, useContext, useState, useEffect } from 'react';\nimport { adminAuthAPI } from '../services/adminApi';\nimport toast from 'react-hot-toast';\n\nconst AdminAuthContext = createContext(null);\n\nexport const useAdminAuth = () => {\n  const ctx = useContext(AdminAuthContext);\n  if (!ctx) throw new Error('useAdminAuth must be used within AdminAuthProvider');\n  return ctx;\n};\n\nexport function AdminAuthProvider({ children }) {\n  const [admin, setAdmin] = useState(() => {\n    try {\n      const saved = localStorage.getItem('adminUser');\n      return saved ? JSON.parse(saved) : null;\n    } catch {\n      return null;\n    }\n  });\n  const [token, setToken] = useState(() => localStorage.getItem('adminToken'));\n  const [loading, setLoading] = useState(false);\n\n  const isAuthenticated = !!token;\n\n  useEffect(() => {\n    if (token && !admin) {\n      setLoading(true);\n      adminAuthAPI\n        .getProfile()\n        .then((res) => {\n          setAdmin(res.data.admin);\n          localStorage.setItem('adminUser', JSON.stringify(res.data.admin));\n        })\n        .catch(() => logout())\n        .finally(() => setLoading(false));\n    }\n  }, [token]);\n\n  const login = async (credentials) => {\n    setLoading(true);\n    try {\n      const res = await adminAuthAPI.login(credentials);\n      const { token: tk, admin: a } = res.data;\n      setToken(tk);\n      setAdmin(a);\n      localStorage.setItem('adminToken', tk);\n      localStorage.setItem('adminUser', JSON.stringify(a));\n      toast.success(`Welcome back, ${a.name}!`);\n      return { success: true };\n    } catch (err) {\n      const message = err.response?.data?.message || 'Login failed';\n      toast.error(message);\n      return { success: false, message };\n    } finally {\n      setLoading(false);\n    }\n  };\n\n  const logout = () => {\n    setToken(null);\n    setAdmin(null);\n    localStorage.removeItem('adminToken');\n    localStorage.removeItem('adminUser');\n  };\n\n  return (\n    <AdminAuthContext.Provider value={{ admin, isAuthenticated, loading, login, logout }}>\n      {children}\n    </AdminAuthContext.Provider>\n  );\n}\n",
  "src/components/ProtectedAdminRoute.jsx": "import { Navigate } from 'react-router-dom';\nimport { useAdminAuth } from '../context/AdminAuthContext';\nimport LoadingSpinner from './LoadingSpinner';\n\nexport default function ProtectedAdminRoute({ children }) {\n  const { isAuthenticated, loading } = useAdminAuth();\n\n  if (loading) return <div className=\"h-screen flex items-center justify-center bg-[#0a0a1a]\"><LoadingSpinner size=\"lg\" /></div>;\n  if (!isAuthenticated) return <Navigate to=\"/staff-login\" replace />;\n\n  return children;\n}\n",
  "src/components/AdminNotificationBell.jsx": "import { useState, useEffect, useRef, useCallback } from 'react';\nimport { Bell } from 'lucide-react';\nimport { adminAPI } from '../services/adminApi';\n\nconst TYPE_DOT = { info: 'bg-blue-400', warning: 'bg-amber-400', action: 'bg-purple-400' };\n\nexport default function AdminNotificationBell() {\n  const [open, setOpen] = useState(false);\n  const [notifications, setNotifications] = useState([]);\n  const [unreadCount, setUnreadCount] = useState(0);\n  const ref = useRef(null);\n\n  const load = useCallback(() => {\n    adminAPI.listNotifications()\n      .then((res) => {\n        setNotifications(res.data.notifications);\n        setUnreadCount(res.data.unreadCount);\n      })\n      .catch(() => {});\n  }, []);\n\n  useEffect(() => {\n    load();\n    const interval = setInterval(load, 60000); // poll every minute — real data, not static\n    return () => clearInterval(interval);\n  }, [load]);\n\n  useEffect(() => {\n    const onClickOutside = (e) => {\n      if (ref.current && !ref.current.contains(e.target)) setOpen(false);\n    };\n    document.addEventListener('mousedown', onClickOutside);\n    return () => document.removeEventListener('mousedown', onClickOutside);\n  }, []);\n\n  const handleOpen = () => {\n    const next = !open;\n    setOpen(next);\n    if (next) load();\n  };\n\n  const markAllRead = async () => {\n    try {\n      await adminAPI.markAllNotificationsRead();\n      setUnreadCount(0);\n      setNotifications((prev) => prev.map((n) => ({ ...n, is_read: true })));\n    } catch {\n      // non-critical — leave state as-is, next poll will reconcile\n    }\n  };\n\n  return (\n    <div className=\"relative\" ref={ref}>\n      <button\n        onClick={handleOpen}\n        className=\"relative w-9 h-9 rounded-lg bg-white/5 hover:bg-white/10 flex items-center justify-center cursor-pointer\"\n      >\n        <Bell className=\"w-4 h-4 text-slate-300\" />\n        {unreadCount > 0 && (\n          <span className=\"absolute -top-1 -right-1 min-w-[18px] h-[18px] px-1 rounded-full bg-red-500 text-white text-[10px] font-bold flex items-center justify-center\">\n            {unreadCount > 9 ? '9+' : unreadCount}\n          </span>\n        )}\n      </button>\n\n      {open && (\n        <div className=\"absolute right-0 mt-2 w-80 max-h-96 overflow-y-auto bg-[#141432] border border-[#2a2a5a] rounded-xl shadow-xl z-50\">\n          <div className=\"flex items-center justify-between px-4 py-3 border-b border-[#2a2a5a]\">\n            <p className=\"text-white text-sm font-semibold\">Notifications</p>\n            {unreadCount > 0 && (\n              <button onClick={markAllRead} className=\"text-xs text-purple-300 hover:text-purple-200 cursor-pointer\">\n                Mark all read\n              </button>\n            )}\n          </div>\n          {notifications.length === 0 ? (\n            <p className=\"p-4 text-sm text-slate-500 italic\">No notifications yet.</p>\n          ) : (\n            <div className=\"divide-y divide-[#2a2a5a]\">\n              {notifications.map((n) => (\n                <div key={n.id} className={`p-3 flex gap-2 ${n.is_read ? 'opacity-60' : ''}`}>\n                  <span className={`w-2 h-2 rounded-full mt-1.5 flex-shrink-0 ${TYPE_DOT[n.type] || TYPE_DOT.info}`} />\n                  <div className=\"min-w-0\">\n                    <p className=\"text-white text-xs font-medium\">{n.title}</p>\n                    <p className=\"text-slate-400 text-xs mt-0.5\">{n.message}</p>\n                    <p className=\"text-slate-500 text-[10px] mt-1\">{new Date(n.created_at).toLocaleString()}</p>\n                  </div>\n                </div>\n              ))}\n            </div>\n          )}\n        </div>\n      )}\n    </div>\n  );\n}\n",
  "src/layouts/AdminLayout.jsx": "import { NavLink, Outlet, useNavigate } from 'react-router-dom';\nimport {\n  LayoutDashboard, Users, BookOpen, UserCog, BarChart3, LogOut, ShieldCheck,\n  SlidersHorizontal, History, AlertTriangle, ClipboardCheck, TrendingDown,\n} from 'lucide-react';\nimport { useAdminAuth } from '../context/AdminAuthContext';\nimport AdminNotificationBell from '../components/AdminNotificationBell';\n\nconst NAV = [\n  { to: '/admin', label: 'Admin Dashboard', icon: LayoutDashboard, end: true },\n  { to: '/admin/students', label: 'Students', icon: Users },\n  { to: '/admin/staff', label: 'Staff Members', icon: UserCog },\n  { to: '/admin/questions', label: 'Question Bank', icon: BookOpen },\n  { to: '/admin/evaluations', label: 'Evaluations', icon: ClipboardCheck },\n  { to: '/admin/analytics', label: 'Analytics', icon: BarChart3 },\n  { to: '/admin/skill-gaps', label: 'Skill Gaps', icon: TrendingDown },\n  { to: '/admin/settings', label: 'Settings', icon: SlidersHorizontal },\n  { to: '/admin/alerts', label: 'Alerts', icon: AlertTriangle },\n  { to: '/admin/audit-log', label: 'Audit Log', icon: History },\n];\n\nexport default function AdminLayout() {\n  const { admin, logout } = useAdminAuth();\n  const navigate = useNavigate();\n\n  const handleLogout = () => {\n    logout();\n    navigate('/staff-login');\n  };\n\n  return (\n    <div className=\"flex h-screen overflow-hidden bg-[#0a0a1a]\">\n      <aside className=\"w-64 flex-shrink-0 bg-[#0f0f2a] border-r border-[#2a2a5a] flex flex-col\">\n        <div className=\"p-5 flex items-center gap-2 border-b border-[#2a2a5a]\">\n          <div className=\"w-9 h-9 rounded-lg bg-gradient-to-r from-purple-600 to-blue-600 flex items-center justify-center\">\n            <ShieldCheck className=\"w-5 h-5 text-white\" />\n          </div>\n          <div>\n            <p className=\"text-white font-semibold text-sm leading-tight\">Admin Portal</p>\n            <p className=\"text-slate-500 text-xs\">{admin?.role === 'admin' ? 'Administrator' : 'Staff'}</p>\n          </div>\n        </div>\n\n        <nav className=\"flex-1 p-3 space-y-1 overflow-y-auto\">\n          {NAV.map(({ to, label, icon: Icon, end }) => (\n            <NavLink\n              key={to}\n              to={to}\n              end={end}\n              className={({ isActive }) =>\n                `flex items-center gap-3 px-3 py-2.5 rounded-xl text-sm font-medium transition-colors ${\n                  isActive ? 'bg-purple-600/20 text-purple-300 border border-purple-500/30' : 'text-slate-400 hover:text-white hover:bg-white/5'\n                }`\n              }\n            >\n              <Icon className=\"w-4 h-4\" />\n              {label}\n            </NavLink>\n          ))}\n        </nav>\n\n        <div className=\"p-3 border-t border-[#2a2a5a]\">\n          <div className=\"px-3 py-2 mb-2\">\n            <p className=\"text-white text-sm font-medium truncate\">{admin?.name}</p>\n            <p className=\"text-slate-500 text-xs truncate\">{admin?.email}</p>\n          </div>\n          <button\n            onClick={handleLogout}\n            className=\"w-full flex items-center gap-2 px-3 py-2 rounded-xl text-sm text-slate-400 hover:text-red-300 hover:bg-red-500/10 transition-colors cursor-pointer\"\n          >\n            <LogOut className=\"w-4 h-4\" />\n            Logout\n          </button>\n        </div>\n      </aside>\n\n      <div className=\"flex-1 flex flex-col overflow-hidden\">\n        <header className=\"flex items-center justify-end px-4 lg:px-6 py-3 border-b border-[#2a2a5a] bg-[#0f0f2a]/60\">\n          <AdminNotificationBell />\n        </header>\n\n        <main className=\"flex-1 overflow-y-auto p-4 lg:p-6\">\n          <div className=\"max-w-7xl mx-auto animate-fade-in\">\n            <Outlet />\n          </div>\n        </main>\n      </div>\n    </div>\n  );\n}\n",
  "src/pages/admin/AdminLoginPage.jsx": "import { useState } from 'react';\nimport { useNavigate, Link } from 'react-router-dom';\nimport { Eye, EyeOff, ArrowRight, ShieldCheck } from 'lucide-react';\nimport { useAdminAuth } from '../../context/AdminAuthContext';\nimport Button from '../../components/Button';\n\nexport default function AdminLoginPage() {\n  const { login, loading } = useAdminAuth();\n  const navigate = useNavigate();\n  const [form, setForm] = useState({ email: '', password: '' });\n  const [showPw, setShowPw] = useState(false);\n\n  const handleSubmit = async (e) => {\n    e.preventDefault();\n    const result = await login(form);\n    if (result?.success) navigate('/admin/dashboard');\n  };\n\n  return (\n    <div className=\"min-h-screen flex items-center justify-center bg-[#0a0a1a] px-4\">\n      <div className=\"w-full max-w-md\">\n        <div className=\"glass-card p-8\">\n          <div className=\"flex flex-col items-center mb-6\">\n            <div className=\"w-12 h-12 rounded-xl bg-gradient-to-r from-purple-600 to-blue-600 flex items-center justify-center mb-3\">\n              <ShieldCheck className=\"w-6 h-6 text-white\" />\n            </div>\n            <h1 className=\"text-xl font-bold text-white\">Staff / Admin Portal</h1>\n            <p className=\"text-sm text-slate-400 mt-1\">Authorized staff only</p>\n          </div>\n\n          <form onSubmit={handleSubmit} className=\"space-y-4\">\n            <div>\n              <label className=\"text-sm text-slate-300 mb-1.5 block\">Email</label>\n              <input\n                type=\"email\"\n                required\n                value={form.email}\n                onChange={(e) => setForm((p) => ({ ...p, email: e.target.value }))}\n                className=\"w-full px-4 py-2.5 rounded-xl bg-[#0f0f2a] border border-[#2a2a5a] text-white placeholder-slate-500 focus:outline-none focus:border-purple-500/50\"\n                placeholder=\"you@college.edu\"\n              />\n            </div>\n\n            <div>\n              <label className=\"text-sm text-slate-300 mb-1.5 block\">Password</label>\n              <div className=\"relative\">\n                <input\n                  type={showPw ? 'text' : 'password'}\n                  required\n                  value={form.password}\n                  onChange={(e) => setForm((p) => ({ ...p, password: e.target.value }))}\n                  className=\"w-full px-4 py-2.5 rounded-xl bg-[#0f0f2a] border border-[#2a2a5a] text-white placeholder-slate-500 focus:outline-none focus:border-purple-500/50 pr-10\"\n                  placeholder=\"••••••••\"\n                />\n                <button\n                  type=\"button\"\n                  onClick={() => setShowPw((p) => !p)}\n                  className=\"absolute right-3 top-1/2 -translate-y-1/2 text-slate-500 hover:text-slate-300 cursor-pointer\"\n                >\n                  {showPw ? <EyeOff className=\"w-4 h-4\" /> : <Eye className=\"w-4 h-4\" />}\n                </button>\n              </div>\n            </div>\n\n            <Button type=\"submit\" loading={loading} className=\"w-full\" icon={ArrowRight}>\n              Sign In\n            </Button>\n          </form>\n\n          <p className=\"text-center text-sm text-slate-400 mt-6\">\n            Not staff?{' '}\n            <Link to=\"/login\" className=\"text-purple-400 hover:text-purple-300 font-medium\">\n              Go to student login\n            </Link>\n          </p>\n        </div>\n      </div>\n    </div>\n  );\n}\n",
  "src/pages/admin/AdminDashboardPage.jsx": "import { useState, useEffect } from 'react';\nimport { Link } from 'react-router-dom';\nimport { Users, UserCheck, Mic, Gauge, BookOpen, AlertTriangle } from 'lucide-react';\nimport { AreaChart, Area, BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer } from 'recharts';\nimport Card, { CardHeader, CardTitle } from '../../components/Card';\nimport LoadingSpinner from '../../components/LoadingSpinner';\nimport ErrorMessage from '../../components/ErrorMessage';\nimport { adminAPI } from '../../services/adminApi';\n\nfunction StatTile({ icon: Icon, label, value }) {\n  return (\n    <Card hover={false} className=\"flex items-center gap-4\">\n      <div className=\"w-11 h-11 rounded-xl bg-purple-600/20 flex items-center justify-center flex-shrink-0\">\n        <Icon className=\"w-5 h-5 text-purple-400\" />\n      </div>\n      <div>\n        <p className=\"text-2xl font-bold text-white\">{value}</p>\n        <p className=\"text-xs text-slate-400\">{label}</p>\n      </div>\n    </Card>\n  );\n}\n\nexport default function AdminDashboardPage() {\n  const [stats, setStats] = useState(null);\n  const [loading, setLoading] = useState(true);\n  const [error, setError] = useState('');\n\n  useEffect(() => {\n    adminAPI.getDashboard()\n      .then((res) => setStats(res.data.stats))\n      .catch((err) => setError(err.response?.data?.message || 'Could not load dashboard'))\n      .finally(() => setLoading(false));\n  }, []);\n\n  if (loading) return <div className=\"h-64 flex items-center justify-center\"><LoadingSpinner size=\"lg\" /></div>;\n  if (error) return <ErrorMessage message={error} />;\n  if (!stats) return null;\n\n  return (\n    <div className=\"space-y-6\">\n      <div>\n        <h1 className=\"text-2xl font-bold text-white\">Admin Dashboard</h1>\n        <p className=\"text-slate-400 mt-1 text-sm\">Platform-wide student performance at a glance</p>\n      </div>\n\n      <div className=\"grid sm:grid-cols-2 lg:grid-cols-5 gap-4\">\n        <StatTile icon={Users} label=\"Total Students\" value={stats.totalStudents} />\n        <StatTile icon={UserCheck} label=\"Active Students\" value={stats.activeStudents} />\n        <StatTile icon={Mic} label=\"Interviews Completed\" value={stats.interviewsCompleted} />\n        <StatTile icon={Gauge} label=\"Avg Interview Score\" value={`${stats.averageInterviewScore}/100`} />\n        <StatTile icon={BookOpen} label=\"Active Questions\" value={stats.activeQuestions} />\n      </div>\n\n      <div className=\"grid lg:grid-cols-2 gap-6\">\n        <Card>\n          <CardHeader><CardTitle>Average Score — Last 30 Days</CardTitle></CardHeader>\n          <div className=\"h-56\">\n            <ResponsiveContainer>\n              <AreaChart data={stats.performanceTrend}>\n                <defs>\n                  <linearGradient id=\"adminTrend\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\">\n                    <stop offset=\"0%\" stopColor=\"#7c3aed\" stopOpacity={0.4} />\n                    <stop offset=\"100%\" stopColor=\"#7c3aed\" stopOpacity={0} />\n                  </linearGradient>\n                </defs>\n                <XAxis dataKey=\"date\" tick={{ fill: '#94a3b8', fontSize: 10 }} axisLine={false} tickLine={false} />\n                <YAxis domain={[0, 100]} tick={{ fill: '#64748b', fontSize: 12 }} axisLine={false} tickLine={false} />\n                <Tooltip contentStyle={{ background: '#141432', border: '1px solid #2a2a5a', borderRadius: '12px', color: '#f1f5f9' }} />\n                <Area type=\"monotone\" dataKey=\"averageScore\" stroke=\"#7c3aed\" strokeWidth={2} fill=\"url(#adminTrend)\" connectNulls />\n              </AreaChart>\n            </ResponsiveContainer>\n          </div>\n        </Card>\n\n        <Card>\n          <CardHeader><CardTitle>Interviews Completed — Per Week</CardTitle></CardHeader>\n          <div className=\"h-56\">\n            <ResponsiveContainer>\n              <BarChart data={stats.weeklyInterviews}>\n                <XAxis dataKey=\"weekStarting\" tick={{ fill: '#94a3b8', fontSize: 10 }} axisLine={false} tickLine={false} />\n                <YAxis allowDecimals={false} tick={{ fill: '#64748b', fontSize: 12 }} axisLine={false} tickLine={false} />\n                <Tooltip contentStyle={{ background: '#141432', border: '1px solid #2a2a5a', borderRadius: '12px', color: '#f1f5f9' }} />\n                <Bar dataKey=\"interviews\" fill=\"#7c3aed\" radius={[6, 6, 0, 0]} />\n              </BarChart>\n            </ResponsiveContainer>\n          </div>\n        </Card>\n      </div>\n\n      <Card>\n        <CardHeader><CardTitle icon={AlertTriangle}>Students Needing Attention (score below {stats.attentionThreshold})</CardTitle></CardHeader>\n        {stats.studentsNeedingAttention.length === 0 ? (\n          <p className=\"text-sm text-slate-500 italic\">No students currently flagged.</p>\n        ) : (\n          <div className=\"space-y-2\">\n            {stats.studentsNeedingAttention.map((s) => (\n              <Link\n                key={s.id}\n                to={`/admin/students?search=${encodeURIComponent(s.email)}`}\n                className=\"flex items-center justify-between p-3 rounded-xl bg-[#0f0f2a] border border-[#2a2a5a] hover:border-red-500/40 transition-colors\"\n              >\n                <div>\n                  <p className=\"text-white text-sm font-medium\">{s.name}</p>\n                  <p className=\"text-slate-500 text-xs\">{s.email} {s.college ? `· ${s.college}` : ''}</p>\n                </div>\n                <span className=\"text-red-400 font-bold text-sm\">{s.overallScore}/100</span>\n              </Link>\n            ))}\n          </div>\n        )}\n      </Card>\n    </div>\n  );\n}\n",
  "src/pages/admin/AdminStudentsPage.jsx": "import { useState, useEffect, useCallback } from 'react';\nimport { useSearchParams } from 'react-router-dom';\nimport toast from 'react-hot-toast';\nimport { Search, Download, Eye, Ban, RotateCcw, X } from 'lucide-react';\nimport Card from '../../components/Card';\nimport Button from '../../components/Button';\nimport LoadingSpinner from '../../components/LoadingSpinner';\nimport ErrorMessage from '../../components/ErrorMessage';\nimport { adminAPI } from '../../services/adminApi';\n\nfunction StudentDetailModal({ studentId, onClose }) {\n  const [detail, setDetail] = useState(null);\n  const [loading, setLoading] = useState(true);\n\n  useEffect(() => {\n    adminAPI.getStudent(studentId)\n      .then((res) => setDetail(res.data.student))\n      .catch(() => toast.error('Could not load student detail'))\n      .finally(() => setLoading(false));\n  }, [studentId]);\n\n  return (\n    <div className=\"fixed inset-0 bg-black/60 flex items-center justify-center z-50 p-4\" onClick={onClose}>\n      <div className=\"bg-[#141432] border border-[#2a2a5a] rounded-2xl max-w-2xl w-full max-h-[85vh] overflow-y-auto p-6\" onClick={(e) => e.stopPropagation()}>\n        <div className=\"flex items-center justify-between mb-4\">\n          <h2 className=\"text-lg font-bold text-white\">Student Detail</h2>\n          <button onClick={onClose} className=\"text-slate-400 hover:text-white cursor-pointer\"><X className=\"w-5 h-5\" /></button>\n        </div>\n        {loading ? <LoadingSpinner /> : detail ? (\n          <div className=\"space-y-4 text-sm\">\n            <div>\n              <p className=\"text-white font-semibold\">{detail.name}</p>\n              <p className=\"text-slate-400\">{detail.email} {detail.college ? `· ${detail.college}` : ''}</p>\n            </div>\n            {detail.scores && (\n              <div className=\"grid grid-cols-3 gap-2\">\n                {['resume_score', 'ats_score', 'interview_score', 'communication_score', 'coding_score', 'aptitude_score'].map((k) => (\n                  <div key={k} className=\"bg-[#0f0f2a] rounded-lg p-2 border border-[#2a2a5a]\">\n                    <p className=\"text-slate-500 text-xs capitalize\">{k.replace('_score', '')}</p>\n                    <p className=\"text-white font-bold\">{Math.round(detail.scores[k] || 0)}</p>\n                  </div>\n                ))}\n              </div>\n            )}\n            <div>\n              <p className=\"text-slate-300 font-medium mb-1\">Recent Interviews ({detail.recentInterviews.length})</p>\n              {detail.recentInterviews.slice(0, 5).map((iv) => (\n                <p key={iv.id} className=\"text-slate-500 text-xs\">{iv.type} — {iv.role} — {iv.status} — {Math.round(iv.total_score || 0)}/100</p>\n              ))}\n            </div>\n          </div>\n        ) : <p className=\"text-slate-500\">Not found.</p>}\n      </div>\n    </div>\n  );\n}\n\nexport default function AdminStudentsPage() {\n  const [searchParams] = useSearchParams();\n  const [students, setStudents] = useState([]);\n  const [loading, setLoading] = useState(true);\n  const [error, setError] = useState('');\n  const [search, setSearch] = useState(searchParams.get('search') || '');\n  const [viewingId, setViewingId] = useState(null);\n\n  const load = useCallback((q = search) => {\n    setLoading(true);\n    adminAPI.listStudents(q)\n      .then((res) => setStudents(res.data.students))\n      .catch((err) => setError(err.response?.data?.message || 'Could not load students'))\n      .finally(() => setLoading(false));\n  }, [search]);\n\n  useEffect(() => { load(search); }, []); // eslint-disable-line\n\n  const handleSearch = (e) => {\n    e.preventDefault();\n    load(search);\n  };\n\n  const toggleActive = async (student) => {\n    try {\n      if (student.isActive) {\n        await adminAPI.deactivateStudent(student.id);\n        toast.success(`${student.name} deactivated`);\n      } else {\n        await adminAPI.reactivateStudent(student.id);\n        toast.success(`${student.name} reactivated`);\n      }\n      load(search);\n    } catch (err) {\n      toast.error(err.response?.data?.message || 'Action failed');\n    }\n  };\n\n  const exportCsv = async () => {\n    try {\n      const res = await adminAPI.exportStudentsCsv();\n      const url = URL.createObjectURL(new Blob([res.data], { type: 'text/csv' }));\n      const a = document.createElement('a');\n      a.href = url; a.download = 'students.csv'; a.click();\n      URL.revokeObjectURL(url);\n    } catch {\n      toast.error('Export failed');\n    }\n  };\n\n  return (\n    <div className=\"space-y-6\">\n      <div className=\"flex flex-wrap items-center justify-between gap-3\">\n        <div>\n          <h1 className=\"text-2xl font-bold text-white\">Student Management</h1>\n          <p className=\"text-slate-400 mt-1 text-sm\">{students.length} students</p>\n        </div>\n        <Button variant=\"secondary\" icon={Download} onClick={exportCsv}>Export CSV</Button>\n      </div>\n\n      <form onSubmit={handleSearch} className=\"flex gap-2 max-w-md\">\n        <div className=\"relative flex-1\">\n          <Search className=\"w-4 h-4 text-slate-500 absolute left-3 top-1/2 -translate-y-1/2\" />\n          <input\n            value={search}\n            onChange={(e) => setSearch(e.target.value)}\n            placeholder=\"Search name, email, or college...\"\n            className=\"w-full pl-9 pr-3 py-2.5 rounded-xl bg-[#0f0f2a] border border-[#2a2a5a] text-white placeholder-slate-500 text-sm focus:outline-none focus:border-purple-500/50\"\n          />\n        </div>\n        <Button type=\"submit\" variant=\"secondary\">Search</Button>\n      </form>\n\n      {loading ? <div className=\"h-40 flex items-center justify-center\"><LoadingSpinner /></div>\n        : error ? <ErrorMessage message={error} />\n        : (\n        <Card hover={false} className=\"!p-0 overflow-hidden\">\n          <div className=\"overflow-x-auto\">\n            <table className=\"w-full text-sm\">\n              <thead className=\"bg-[#0f0f2a] text-slate-400 text-xs uppercase\">\n                <tr>\n                  <th className=\"text-left px-4 py-3\">Name</th>\n                  <th className=\"text-left px-4 py-3\">College</th>\n                  <th className=\"text-left px-4 py-3\">Interviews</th>\n                  <th className=\"text-left px-4 py-3\">Avg Score</th>\n                  <th className=\"text-left px-4 py-3\">Last Active</th>\n                  <th className=\"text-left px-4 py-3\">Status</th>\n                  <th className=\"text-right px-4 py-3\">Actions</th>\n                </tr>\n              </thead>\n              <tbody>\n                {students.map((s) => (\n                  <tr key={s.id} className=\"border-t border-[#2a2a5a] hover:bg-white/5\">\n                    <td className=\"px-4 py-3\">\n                      <p className=\"text-white font-medium\">{s.name}</p>\n                      <p className=\"text-slate-500 text-xs\">{s.email}</p>\n                    </td>\n                    <td className=\"px-4 py-3 text-slate-400\">{s.college || '—'}</td>\n                    <td className=\"px-4 py-3 text-slate-400\">{s.interviews}</td>\n                    <td className=\"px-4 py-3 text-slate-400\">{s.averageScore ?? '—'}</td>\n                    <td className=\"px-4 py-3 text-slate-500 text-xs\">{s.lastActiveAt ? new Date(s.lastActiveAt).toLocaleDateString() : 'Never'}</td>\n                    <td className=\"px-4 py-3\">\n                      <span className={`text-xs px-2 py-1 rounded-full ${s.isActive ? 'bg-emerald-500/15 text-emerald-300' : 'bg-red-500/15 text-red-300'}`}>\n                        {s.isActive ? 'Active' : 'Deactivated'}\n                      </span>\n                    </td>\n                    <td className=\"px-4 py-3 text-right space-x-2 whitespace-nowrap\">\n                      <button onClick={() => setViewingId(s.id)} className=\"text-slate-400 hover:text-purple-300 cursor-pointer\" title=\"View\"><Eye className=\"w-4 h-4 inline\" /></button>\n                      <button\n                        onClick={() => toggleActive(s)}\n                        className={`cursor-pointer ${s.isActive ? 'text-slate-400 hover:text-red-400' : 'text-slate-400 hover:text-emerald-400'}`}\n                        title={s.isActive ? 'Deactivate' : 'Reactivate'}\n                      >\n                        {s.isActive ? <Ban className=\"w-4 h-4 inline\" /> : <RotateCcw className=\"w-4 h-4 inline\" />}\n                      </button>\n                    </td>\n                  </tr>\n                ))}\n                {students.length === 0 && (\n                  <tr><td colSpan={7} className=\"text-center py-8 text-slate-500\">No students found.</td></tr>\n                )}\n              </tbody>\n            </table>\n          </div>\n        </Card>\n      )}\n\n      {viewingId && <StudentDetailModal studentId={viewingId} onClose={() => setViewingId(null)} />}\n    </div>\n  );\n}\n",
  "src/pages/admin/AdminQuestionsPage.jsx": "import { useState, useEffect, useCallback } from 'react';\nimport toast from 'react-hot-toast';\nimport { Plus, Pencil, Ban, RotateCcw, X } from 'lucide-react';\nimport Card from '../../components/Card';\nimport Button from '../../components/Button';\nimport LoadingSpinner from '../../components/LoadingSpinner';\nimport ErrorMessage from '../../components/ErrorMessage';\nimport { adminAPI } from '../../services/adminApi';\n\nconst TYPES = ['aptitude', 'technical', 'coding', 'behavioural'];\nconst DIFFICULTIES = ['Easy', 'Medium', 'Hard'];\n\nfunction emptyForm() {\n  return {\n    type: 'aptitude', category: '', difficulty: 'Medium', questionText: '',\n    options: ['', '', '', ''], correctAnswer: '', explanation: '',\n    expectedConcepts: '',\n  };\n}\n\nfunction QuestionFormModal({ initial, onClose, onSaved }) {\n  const [form, setForm] = useState(initial || emptyForm());\n  const [saving, setSaving] = useState(false);\n  const isEdit = !!initial?.id;\n\n  const submit = async (e) => {\n    e.preventDefault();\n    setSaving(true);\n    try {\n      let payload = {};\n      if (form.type === 'aptitude') {\n        payload = { options: form.options.filter(Boolean), correctAnswer: form.correctAnswer, explanation: form.explanation };\n      } else if (form.type === 'technical') {\n        payload = { technology: form.category, expectedConcepts: form.expectedConcepts.split(',').map((s) => s.trim()).filter(Boolean) };\n      } else if (form.type === 'behavioural') {\n        payload = { topic: form.category };\n      } else if (form.type === 'coding') {\n        payload = { title: form.questionText.slice(0, 80), description: form.questionText };\n      }\n\n      if (isEdit) {\n        await adminAPI.updateQuestion(initial.id, {\n          category: form.category, difficulty: form.difficulty, questionText: form.questionText, payload,\n        });\n        toast.success('Question updated');\n      } else {\n        await adminAPI.createQuestion({\n          type: form.type, category: form.category, difficulty: form.difficulty, questionText: form.questionText, payload,\n        });\n        toast.success('Question added');\n      }\n      onSaved();\n    } catch (err) {\n      toast.error(err.response?.data?.message || 'Save failed');\n    } finally {\n      setSaving(false);\n    }\n  };\n\n  return (\n    <div className=\"fixed inset-0 bg-black/60 flex items-center justify-center z-50 p-4\" onClick={onClose}>\n      <form onSubmit={submit} className=\"bg-[#141432] border border-[#2a2a5a] rounded-2xl max-w-xl w-full max-h-[88vh] overflow-y-auto p-6 space-y-4\" onClick={(e) => e.stopPropagation()}>\n        <div className=\"flex items-center justify-between\">\n          <h2 className=\"text-lg font-bold text-white\">{isEdit ? 'Edit Question' : 'Add Question'}</h2>\n          <button type=\"button\" onClick={onClose} className=\"text-slate-400 hover:text-white cursor-pointer\"><X className=\"w-5 h-5\" /></button>\n        </div>\n\n        <div className=\"grid grid-cols-2 gap-3\">\n          <div>\n            <label className=\"text-xs text-slate-400 mb-1 block\">Type</label>\n            <select\n              disabled={isEdit}\n              value={form.type}\n              onChange={(e) => setForm((p) => ({ ...p, type: e.target.value }))}\n              className=\"w-full px-3 py-2 rounded-lg bg-[#0f0f2a] border border-[#2a2a5a] text-white text-sm disabled:opacity-50\"\n            >\n              {TYPES.map((t) => <option key={t} value={t}>{t}</option>)}\n            </select>\n          </div>\n          <div>\n            <label className=\"text-xs text-slate-400 mb-1 block\">Difficulty</label>\n            <select\n              value={form.difficulty}\n              onChange={(e) => setForm((p) => ({ ...p, difficulty: e.target.value }))}\n              className=\"w-full px-3 py-2 rounded-lg bg-[#0f0f2a] border border-[#2a2a5a] text-white text-sm\"\n            >\n              {DIFFICULTIES.map((d) => <option key={d} value={d}>{d}</option>)}\n            </select>\n          </div>\n        </div>\n\n        <div>\n          <label className=\"text-xs text-slate-400 mb-1 block\">\n            {form.type === 'technical' ? 'Technology (e.g. Java, React)' : form.type === 'behavioural' ? 'Topic (e.g. Leadership)' : 'Category'}\n          </label>\n          <input\n            required\n            value={form.category}\n            onChange={(e) => setForm((p) => ({ ...p, category: e.target.value }))}\n            className=\"w-full px-3 py-2 rounded-lg bg-[#0f0f2a] border border-[#2a2a5a] text-white text-sm\"\n          />\n        </div>\n\n        <div>\n          <label className=\"text-xs text-slate-400 mb-1 block\">Question Text</label>\n          <textarea\n            required\n            rows={3}\n            value={form.questionText}\n            onChange={(e) => setForm((p) => ({ ...p, questionText: e.target.value }))}\n            className=\"w-full px-3 py-2 rounded-lg bg-[#0f0f2a] border border-[#2a2a5a] text-white text-sm\"\n          />\n        </div>\n\n        {form.type === 'aptitude' && (\n          <div className=\"space-y-2\">\n            <label className=\"text-xs text-slate-400 block\">Options</label>\n            {form.options.map((opt, i) => (\n              <input\n                key={i}\n                required\n                value={opt}\n                onChange={(e) => setForm((p) => { const opts = [...p.options]; opts[i] = e.target.value; return { ...p, options: opts }; })}\n                placeholder={`Option ${i + 1}`}\n                className=\"w-full px-3 py-2 rounded-lg bg-[#0f0f2a] border border-[#2a2a5a] text-white text-sm\"\n              />\n            ))}\n            <input\n              required\n              value={form.correctAnswer}\n              onChange={(e) => setForm((p) => ({ ...p, correctAnswer: e.target.value }))}\n              placeholder=\"Correct answer (must match one option exactly)\"\n              className=\"w-full px-3 py-2 rounded-lg bg-[#0f0f2a] border border-amber-500/30 text-white text-sm\"\n            />\n            <input\n              value={form.explanation}\n              onChange={(e) => setForm((p) => ({ ...p, explanation: e.target.value }))}\n              placeholder=\"Explanation (optional)\"\n              className=\"w-full px-3 py-2 rounded-lg bg-[#0f0f2a] border border-[#2a2a5a] text-white text-sm\"\n            />\n          </div>\n        )}\n\n        {form.type === 'technical' && (\n          <div>\n            <label className=\"text-xs text-slate-400 mb-1 block\">Expected Concepts (comma-separated)</label>\n            <input\n              value={form.expectedConcepts}\n              onChange={(e) => setForm((p) => ({ ...p, expectedConcepts: e.target.value }))}\n              className=\"w-full px-3 py-2 rounded-lg bg-[#0f0f2a] border border-[#2a2a5a] text-white text-sm\"\n            />\n          </div>\n        )}\n\n        <Button type=\"submit\" loading={saving} className=\"w-full\">{isEdit ? 'Save Changes' : 'Add Question'}</Button>\n      </form>\n    </div>\n  );\n}\n\nexport default function AdminQuestionsPage() {\n  const [questions, setQuestions] = useState([]);\n  const [loading, setLoading] = useState(true);\n  const [error, setError] = useState('');\n  const [typeFilter, setTypeFilter] = useState('');\n  const [modalState, setModalState] = useState(null); // null | 'new' | question object\n\n  const load = useCallback(() => {\n    setLoading(true);\n    adminAPI.listQuestions(typeFilter ? { type: typeFilter } : {})\n      .then((res) => setQuestions(res.data.questions))\n      .catch((err) => setError(err.response?.data?.message || 'Could not load questions'))\n      .finally(() => setLoading(false));\n  }, [typeFilter]);\n\n  useEffect(() => { load(); }, [load]);\n\n  const toggleActive = async (q) => {\n    try {\n      if (q.is_active) { await adminAPI.deactivateQuestion(q.id); toast.success('Deactivated'); }\n      else { await adminAPI.activateQuestion(q.id); toast.success('Activated'); }\n      load();\n    } catch (err) {\n      toast.error(err.response?.data?.message || 'Action failed');\n    }\n  };\n\n  return (\n    <div className=\"space-y-6\">\n      <div className=\"flex flex-wrap items-center justify-between gap-3\">\n        <div>\n          <h1 className=\"text-2xl font-bold text-white\">Question Bank</h1>\n          <p className=\"text-slate-400 mt-1 text-sm\">{questions.length} questions</p>\n        </div>\n        <Button icon={Plus} onClick={() => setModalState('new')}>Add Question</Button>\n      </div>\n\n      <div className=\"flex gap-2\">\n        {['', ...TYPES].map((t) => (\n          <button\n            key={t || 'all'}\n            onClick={() => setTypeFilter(t)}\n            className={`px-3 py-1.5 rounded-full text-xs font-medium capitalize cursor-pointer ${\n              typeFilter === t ? 'bg-purple-600/30 text-purple-300 border border-purple-500/40' : 'bg-[#0f0f2a] text-slate-400 border border-[#2a2a5a] hover:text-white'\n            }`}\n          >\n            {t || 'All'}\n          </button>\n        ))}\n      </div>\n\n      {loading ? <div className=\"h-40 flex items-center justify-center\"><LoadingSpinner /></div>\n        : error ? <ErrorMessage message={error} />\n        : (\n        <Card hover={false} className=\"!p-0 overflow-hidden\">\n          <div className=\"overflow-x-auto\">\n            <table className=\"w-full text-sm\">\n              <thead className=\"bg-[#0f0f2a] text-slate-400 text-xs uppercase\">\n                <tr>\n                  <th className=\"text-left px-4 py-3\">Question</th>\n                  <th className=\"text-left px-4 py-3\">Type</th>\n                  <th className=\"text-left px-4 py-3\">Category</th>\n                  <th className=\"text-left px-4 py-3\">Difficulty</th>\n                  <th className=\"text-left px-4 py-3\">Usage</th>\n                  <th className=\"text-left px-4 py-3\">Source</th>\n                  <th className=\"text-left px-4 py-3\">Status</th>\n                  <th className=\"text-right px-4 py-3\">Actions</th>\n                </tr>\n              </thead>\n              <tbody>\n                {questions.map((q) => (\n                  <tr key={q.id} className=\"border-t border-[#2a2a5a] hover:bg-white/5\">\n                    <td className=\"px-4 py-3 text-white max-w-xs truncate\" title={q.question_text}>{q.title || q.question_text}</td>\n                    <td className=\"px-4 py-3 text-slate-400 capitalize\">{q.type}</td>\n                    <td className=\"px-4 py-3 text-slate-400\">{q.category}</td>\n                    <td className=\"px-4 py-3 text-slate-400\">{q.difficulty}</td>\n                    <td className=\"px-4 py-3 text-slate-400\">{q.usage_count || 0}{q.usage_count ? ` (avg ${Math.round((q.total_score || 0) / q.usage_count)})` : ''}</td>\n                    <td className=\"px-4 py-3 text-slate-500 text-xs capitalize\">{q.source}</td>\n                    <td className=\"px-4 py-3\">\n                      <span className={`text-xs px-2 py-1 rounded-full ${q.is_active ? 'bg-emerald-500/15 text-emerald-300' : 'bg-red-500/15 text-red-300'}`}>\n                        {q.is_active ? 'Active' : 'Inactive'}\n                      </span>\n                    </td>\n                    <td className=\"px-4 py-3 text-right space-x-2 whitespace-nowrap\">\n                      <button onClick={() => setModalState(q)} className=\"text-slate-400 hover:text-purple-300 cursor-pointer\" title=\"Edit\"><Pencil className=\"w-4 h-4 inline\" /></button>\n                      <button\n                        onClick={() => toggleActive(q)}\n                        className={`cursor-pointer ${q.is_active ? 'text-slate-400 hover:text-red-400' : 'text-slate-400 hover:text-emerald-400'}`}\n                        title={q.is_active ? 'Deactivate' : 'Activate'}\n                      >\n                        {q.is_active ? <Ban className=\"w-4 h-4 inline\" /> : <RotateCcw className=\"w-4 h-4 inline\" />}\n                      </button>\n                    </td>\n                  </tr>\n                ))}\n                {questions.length === 0 && (\n                  <tr><td colSpan={8} className=\"text-center py-8 text-slate-500\">No questions found.</td></tr>\n                )}\n              </tbody>\n            </table>\n          </div>\n        </Card>\n      )}\n\n      {modalState && (\n        <QuestionFormModal\n          initial={modalState === 'new' ? null : {\n            id: modalState.id, type: modalState.type, category: modalState.category, difficulty: modalState.difficulty,\n            questionText: modalState.question_text,\n            options: modalState.payload?.options || ['', '', '', ''],\n            correctAnswer: modalState.payload?.correctAnswer || '',\n            explanation: modalState.payload?.explanation || '',\n            expectedConcepts: (modalState.payload?.expectedConcepts || []).join(', '),\n          }}\n          onClose={() => setModalState(null)}\n          onSaved={() => { setModalState(null); load(); }}\n        />\n      )}\n    </div>\n  );\n}\n",
  "src/pages/admin/AdminStaffPage.jsx": "import { useState, useEffect } from 'react';\nimport toast from 'react-hot-toast';\nimport { UserPlus, Ban, RotateCcw, X } from 'lucide-react';\nimport Card from '../../components/Card';\nimport Button from '../../components/Button';\nimport LoadingSpinner from '../../components/LoadingSpinner';\nimport ErrorMessage from '../../components/ErrorMessage';\nimport { adminAPI } from '../../services/adminApi';\nimport { useAdminAuth } from '../../context/AdminAuthContext';\n\nfunction AddStaffModal({ onClose, onSaved }) {\n  const [form, setForm] = useState({ name: '', email: '', password: '', role: 'staff' });\n  const [saving, setSaving] = useState(false);\n\n  const submit = async (e) => {\n    e.preventDefault();\n    setSaving(true);\n    try {\n      await adminAPI.createStaff(form);\n      toast.success('Staff account created');\n      onSaved();\n    } catch (err) {\n      toast.error(err.response?.data?.message || 'Failed to create account');\n    } finally {\n      setSaving(false);\n    }\n  };\n\n  return (\n    <div className=\"fixed inset-0 bg-black/60 flex items-center justify-center z-50 p-4\" onClick={onClose}>\n      <form onSubmit={submit} className=\"bg-[#141432] border border-[#2a2a5a] rounded-2xl max-w-sm w-full p-6 space-y-4\" onClick={(e) => e.stopPropagation()}>\n        <div className=\"flex items-center justify-between\">\n          <h2 className=\"text-lg font-bold text-white\">Add Staff Account</h2>\n          <button type=\"button\" onClick={onClose} className=\"text-slate-400 hover:text-white cursor-pointer\"><X className=\"w-5 h-5\" /></button>\n        </div>\n        <input required placeholder=\"Name\" value={form.name} onChange={(e) => setForm((p) => ({ ...p, name: e.target.value }))} className=\"w-full px-3 py-2 rounded-lg bg-[#0f0f2a] border border-[#2a2a5a] text-white text-sm\" />\n        <input required type=\"email\" placeholder=\"Email\" value={form.email} onChange={(e) => setForm((p) => ({ ...p, email: e.target.value }))} className=\"w-full px-3 py-2 rounded-lg bg-[#0f0f2a] border border-[#2a2a5a] text-white text-sm\" />\n        <input required type=\"password\" placeholder=\"Password (6+ characters)\" value={form.password} onChange={(e) => setForm((p) => ({ ...p, password: e.target.value }))} className=\"w-full px-3 py-2 rounded-lg bg-[#0f0f2a] border border-[#2a2a5a] text-white text-sm\" />\n        <select value={form.role} onChange={(e) => setForm((p) => ({ ...p, role: e.target.value }))} className=\"w-full px-3 py-2 rounded-lg bg-[#0f0f2a] border border-[#2a2a5a] text-white text-sm\">\n          <option value=\"staff\">Staff</option>\n          <option value=\"admin\">Admin</option>\n        </select>\n        <Button type=\"submit\" loading={saving} className=\"w-full\">Create Account</Button>\n      </form>\n    </div>\n  );\n}\n\nexport default function AdminStaffPage() {\n  const { admin } = useAdminAuth();\n  const [staff, setStaff] = useState([]);\n  const [loading, setLoading] = useState(true);\n  const [error, setError] = useState('');\n  const [showAdd, setShowAdd] = useState(false);\n\n  const loadStaff = () => {\n    setLoading(true);\n    adminAPI.listStaff()\n      .then((res) => setStaff(res.data.staff))\n      .catch((err) => setError(err.response?.data?.message || 'Could not load staff'))\n      .finally(() => setLoading(false));\n  };\n\n  useEffect(() => { loadStaff(); }, []);\n\n  const toggleStaffActive = async (s) => {\n    try {\n      if (s.is_active) { await adminAPI.deactivateStaff(s.id); toast.success('Deactivated'); }\n      else { await adminAPI.reactivateStaff(s.id); toast.success('Reactivated'); }\n      loadStaff();\n    } catch (err) {\n      toast.error(err.response?.data?.message || 'Action failed');\n    }\n  };\n\n  return (\n    <div className=\"space-y-6\">\n      <div className=\"flex flex-wrap items-center justify-between gap-3\">\n        <div>\n          <h1 className=\"text-2xl font-bold text-white\">Staff Members</h1>\n          <p className=\"text-slate-400 mt-1 text-sm\">Manage staff and admin accounts for this portal</p>\n        </div>\n        {admin?.role === 'admin' && (\n          <Button icon={UserPlus} onClick={() => setShowAdd(true)}>Add Staff</Button>\n        )}\n      </div>\n\n      {loading ? <div className=\"h-40 flex items-center justify-center\"><LoadingSpinner /></div>\n        : error ? <ErrorMessage message={error} />\n        : (\n          <Card hover={false} className=\"!p-0 overflow-hidden\">\n            <div className=\"overflow-x-auto\">\n              <table className=\"w-full text-sm\">\n                <thead className=\"bg-[#0f0f2a] text-slate-400 text-xs uppercase\">\n                  <tr>\n                    <th className=\"text-left px-4 py-3\">Name</th>\n                    <th className=\"text-left px-4 py-3\">Role</th>\n                    <th className=\"text-left px-4 py-3\">Last Login</th>\n                    <th className=\"text-left px-4 py-3\">Status</th>\n                    <th className=\"text-right px-4 py-3\">Actions</th>\n                  </tr>\n                </thead>\n                <tbody>\n                  {staff.map((s) => (\n                    <tr key={s.id} className=\"border-t border-[#2a2a5a] hover:bg-white/5\">\n                      <td className=\"px-4 py-3\"><p className=\"text-white font-medium\">{s.name}</p><p className=\"text-slate-500 text-xs\">{s.email}</p></td>\n                      <td className=\"px-4 py-3 text-slate-400 capitalize\">{s.role}</td>\n                      <td className=\"px-4 py-3 text-slate-500 text-xs\">{s.last_login_at ? new Date(s.last_login_at).toLocaleDateString() : 'Never'}</td>\n                      <td className=\"px-4 py-3\">\n                        <span className={`text-xs px-2 py-1 rounded-full ${s.is_active !== false ? 'bg-emerald-500/15 text-emerald-300' : 'bg-red-500/15 text-red-300'}`}>\n                          {s.is_active !== false ? 'Active' : 'Deactivated'}\n                        </span>\n                      </td>\n                      <td className=\"px-4 py-3 text-right\">\n                        {admin?.role === 'admin' && s.id !== admin.id && (\n                          <button\n                            onClick={() => toggleStaffActive(s)}\n                            className={`cursor-pointer ${s.is_active !== false ? 'text-slate-400 hover:text-red-400' : 'text-slate-400 hover:text-emerald-400'}`}\n                          >\n                            {s.is_active !== false ? <Ban className=\"w-4 h-4 inline\" /> : <RotateCcw className=\"w-4 h-4 inline\" />}\n                          </button>\n                        )}\n                      </td>\n                    </tr>\n                  ))}\n                  {staff.length === 0 && (\n                    <tr><td colSpan={5} className=\"text-center py-8 text-slate-500\">No staff accounts yet.</td></tr>\n                  )}\n                </tbody>\n              </table>\n            </div>\n          </Card>\n        )}\n\n      {showAdd && <AddStaffModal onClose={() => setShowAdd(false)} onSaved={() => { setShowAdd(false); loadStaff(); }} />}\n    </div>\n  );\n}\n",
  "src/pages/admin/AdminEvaluationsPage.jsx": "import { useState, useEffect } from 'react';\nimport Card from '../../components/Card';\nimport LoadingSpinner from '../../components/LoadingSpinner';\nimport ErrorMessage from '../../components/ErrorMessage';\nimport { adminAPI } from '../../services/adminApi';\n\nexport default function AdminEvaluationsPage() {\n  const [evaluations, setEvaluations] = useState([]);\n  const [loading, setLoading] = useState(true);\n  const [error, setError] = useState('');\n\n  useEffect(() => {\n    adminAPI.listEvaluations()\n      .then((res) => setEvaluations(res.data.evaluations))\n      .catch((err) => setError(err.response?.data?.message || 'Could not load evaluations'))\n      .finally(() => setLoading(false));\n  }, []);\n\n  if (loading) return <div className=\"h-64 flex items-center justify-center\"><LoadingSpinner size=\"lg\" /></div>;\n  if (error) return <ErrorMessage message={error} />;\n\n  return (\n    <div className=\"space-y-6\">\n      <div>\n        <h1 className=\"text-2xl font-bold text-white\">Evaluations</h1>\n        <p className=\"text-slate-400 mt-1 text-sm\">Recent AI-scored interview responses, newest first</p>\n      </div>\n\n      <div className=\"space-y-3\">\n        {evaluations.length === 0 && (\n          <Card><p className=\"text-slate-500 italic\">No evaluations yet.</p></Card>\n        )}\n        {evaluations.map((ev) => (\n          <Card key={ev.id} hover={false}>\n            <div className=\"flex items-start justify-between gap-4\">\n              <div className=\"flex-1\">\n                <p className=\"text-xs text-slate-500\">{ev.studentName} · {ev.studentEmail} · {ev.interviewType} · {ev.role}</p>\n                <p className=\"text-white text-sm font-medium mt-1\">{ev.questionText}</p>\n                <p className=\"text-slate-400 text-sm mt-1 line-clamp-3\">{ev.userAnswer}</p>\n                {ev.feedback && <p className=\"text-slate-500 text-xs mt-2 italic\">{ev.feedback}</p>}\n              </div>\n              <span className=\"text-lg font-bold text-purple-300 flex-shrink-0\">{Math.round(ev.score || 0)}/100</span>\n            </div>\n          </Card>\n        ))}\n      </div>\n    </div>\n  );\n}\n",
  "src/pages/admin/AdminAnalyticsPage.jsx": "import { useState, useEffect } from 'react';\nimport { BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer } from 'recharts';\nimport Card, { CardHeader, CardTitle } from '../../components/Card';\nimport LoadingSpinner from '../../components/LoadingSpinner';\nimport ErrorMessage from '../../components/ErrorMessage';\nimport { adminAPI } from '../../services/adminApi';\n\nexport default function AdminAnalyticsPage() {\n  const [analytics, setAnalytics] = useState(null);\n  const [loading, setLoading] = useState(true);\n  const [error, setError] = useState('');\n\n  useEffect(() => {\n    adminAPI.getAnalytics()\n      .then((res) => setAnalytics(res.data.analytics))\n      .catch((err) => setError(err.response?.data?.message || 'Could not load analytics'))\n      .finally(() => setLoading(false));\n  }, []);\n\n  if (loading) return <div className=\"h-64 flex items-center justify-center\"><LoadingSpinner size=\"lg\" /></div>;\n  if (error) return <ErrorMessage message={error} />;\n  if (!analytics) return null;\n\n  const categoryData = Object.entries(analytics.averageByCategory).map(([category, score]) => ({ category, score }));\n\n  return (\n    <div className=\"space-y-6\">\n      <div>\n        <h1 className=\"text-2xl font-bold text-white\">Analytics</h1>\n        <p className=\"text-slate-400 mt-1 text-sm\">\n          Across {analytics.studentsCounted} students · Weakest area overall: <span className=\"text-red-300 font-medium capitalize\">{analytics.weakestCategory || 'n/a'}</span>\n        </p>\n      </div>\n\n      <Card>\n        <CardHeader><CardTitle>Average Score by Category</CardTitle></CardHeader>\n        <div className=\"h-64\">\n          <ResponsiveContainer>\n            <BarChart data={categoryData}>\n              <XAxis dataKey=\"category\" tick={{ fill: '#94a3b8', fontSize: 11 }} axisLine={false} tickLine={false} />\n              <YAxis domain={[0, 100]} tick={{ fill: '#64748b', fontSize: 12 }} axisLine={false} tickLine={false} />\n              <Tooltip contentStyle={{ background: '#141432', border: '1px solid #2a2a5a', borderRadius: '12px', color: '#f1f5f9' }} />\n              <Bar dataKey=\"score\" fill=\"#7c3aed\" radius={[6, 6, 0, 0]} />\n            </BarChart>\n          </ResponsiveContainer>\n        </div>\n      </Card>\n    </div>\n  );\n}\n",
  "src/pages/admin/AdminSkillGapsPage.jsx": "import { useState, useEffect } from 'react';\nimport Card, { CardHeader, CardTitle } from '../../components/Card';\nimport LoadingSpinner from '../../components/LoadingSpinner';\nimport ErrorMessage from '../../components/ErrorMessage';\nimport { adminAPI } from '../../services/adminApi';\n\nexport default function AdminSkillGapsPage() {\n  const [analytics, setAnalytics] = useState(null);\n  const [loading, setLoading] = useState(true);\n  const [error, setError] = useState('');\n\n  useEffect(() => {\n    adminAPI.getAnalytics()\n      .then((res) => setAnalytics(res.data.analytics))\n      .catch((err) => setError(err.response?.data?.message || 'Could not load skill gaps'))\n      .finally(() => setLoading(false));\n  }, []);\n\n  if (loading) return <div className=\"h-64 flex items-center justify-center\"><LoadingSpinner size=\"lg\" /></div>;\n  if (error) return <ErrorMessage message={error} />;\n  if (!analytics) return null;\n\n  return (\n    <div className=\"space-y-6\">\n      <div>\n        <h1 className=\"text-2xl font-bold text-white\">Skill Gaps</h1>\n        <p className=\"text-slate-400 mt-1 text-sm\">The weak areas showing up most often across all students' real attempts</p>\n      </div>\n\n      <div className=\"grid lg:grid-cols-2 gap-6\">\n        <Card>\n          <CardHeader><CardTitle>Most Common Aptitude Weak Areas</CardTitle></CardHeader>\n          {analytics.topAptitudeWeakAreas.length === 0 ? <p className=\"text-sm text-slate-500 italic\">No data yet.</p> : (\n            <div className=\"space-y-2\">\n              {analytics.topAptitudeWeakAreas.map((w) => (\n                <div key={w.label} className=\"flex items-center justify-between text-sm\">\n                  <span className=\"text-slate-300\">{w.label}</span>\n                  <span className=\"text-purple-300 font-medium\">{w.count}</span>\n                </div>\n              ))}\n            </div>\n          )}\n        </Card>\n\n        <Card>\n          <CardHeader><CardTitle>Most Common Interview Weaknesses</CardTitle></CardHeader>\n          {analytics.topInterviewWeaknesses.length === 0 ? <p className=\"text-sm text-slate-500 italic\">No data yet.</p> : (\n            <div className=\"space-y-2\">\n              {analytics.topInterviewWeaknesses.map((w) => (\n                <div key={w.label} className=\"flex items-center justify-between text-sm\">\n                  <span className=\"text-slate-300\">{w.label}</span>\n                  <span className=\"text-purple-300 font-medium\">{w.count}</span>\n                </div>\n              ))}\n            </div>\n          )}\n        </Card>\n      </div>\n    </div>\n  );\n}\n",
  "src/pages/admin/AdminSettingsPage.jsx": "import { useState, useEffect } from 'react';\nimport toast from 'react-hot-toast';\nimport { Save } from 'lucide-react';\nimport Card, { CardHeader, CardTitle } from '../../components/Card';\nimport Button from '../../components/Button';\nimport LoadingSpinner from '../../components/LoadingSpinner';\nimport ErrorMessage from '../../components/ErrorMessage';\nimport { adminAPI } from '../../services/adminApi';\nimport { useAdminAuth } from '../../context/AdminAuthContext';\n\nfunction NumberField({ label, hint, value, onChange }) {\n  return (\n    <div>\n      <label className=\"text-xs text-slate-400 mb-1 block\">{label}</label>\n      <input\n        type=\"number\"\n        value={value}\n        onChange={(e) => onChange(e.target.value)}\n        className=\"w-full px-3 py-2 rounded-lg bg-[#0f0f2a] border border-[#2a2a5a] text-white text-sm\"\n      />\n      {hint && <p className=\"text-slate-500 text-xs mt-1\">{hint}</p>}\n    </div>\n  );\n}\n\nexport default function AdminSettingsPage() {\n  const { admin } = useAdminAuth();\n  const canEdit = admin?.role === 'admin';\n\n  const [evaluation, setEvaluation] = useState(null);\n  const [interview, setInterview] = useState(null);\n  const [loading, setLoading] = useState(true);\n  const [error, setError] = useState('');\n  const [savingEval, setSavingEval] = useState(false);\n  const [savingInterview, setSavingInterview] = useState(false);\n\n  useEffect(() => {\n    Promise.all([adminAPI.getEvaluationSettings(), adminAPI.getInterviewSettings()])\n      .then(([evRes, ivRes]) => {\n        setEvaluation(evRes.data.settings);\n        setInterview(ivRes.data.settings);\n      })\n      .catch((err) => setError(err.response?.data?.message || 'Could not load settings'))\n      .finally(() => setLoading(false));\n  }, []);\n\n  const saveEvaluation = async () => {\n    setSavingEval(true);\n    try {\n      const res = await adminAPI.updateEvaluationSettings(evaluation);\n      setEvaluation(res.data.settings);\n      toast.success('Evaluation settings saved');\n    } catch (err) {\n      toast.error(err.response?.data?.message || 'Could not save evaluation settings');\n    } finally {\n      setSavingEval(false);\n    }\n  };\n\n  const saveInterview = async () => {\n    setSavingInterview(true);\n    try {\n      const res = await adminAPI.updateInterviewSettings(interview);\n      setInterview(res.data.settings);\n      toast.success('Interview settings saved');\n    } catch (err) {\n      toast.error(err.response?.data?.message || 'Could not save interview settings');\n    } finally {\n      setSavingInterview(false);\n    }\n  };\n\n  if (loading) return <div className=\"h-64 flex items-center justify-center\"><LoadingSpinner size=\"lg\" /></div>;\n  if (error) return <ErrorMessage message={error} />;\n  if (!evaluation || !interview) return null;\n\n  return (\n    <div className=\"space-y-6\">\n      <div>\n        <h1 className=\"text-2xl font-bold text-white\">Settings</h1>\n        <p className=\"text-slate-400 mt-1 text-sm\">\n          {canEdit\n            ? 'These control live behavior — the attention threshold below is the same one the Dashboard and Alerts use right now.'\n            : 'Staff can view settings; only an admin can change them.'}\n        </p>\n      </div>\n\n      <Card>\n        <CardHeader><CardTitle>Evaluation Settings</CardTitle></CardHeader>\n        <div className=\"grid sm:grid-cols-2 gap-4\">\n          <NumberField\n            label=\"Passing score\"\n            hint=\"Score (0-100) considered a pass on an interview/evaluation.\"\n            value={evaluation.passingScore}\n            onChange={(v) => setEvaluation((p) => ({ ...p, passingScore: v }))}\n          />\n          <NumberField\n            label=\"Attention threshold\"\n            hint=\"Students with an overall score below this are flagged on the Dashboard and Alerts.\"\n            value={evaluation.attentionThreshold}\n            onChange={(v) => setEvaluation((p) => ({ ...p, attentionThreshold: v }))}\n          />\n        </div>\n        {canEdit && (\n          <Button icon={Save} loading={savingEval} onClick={saveEvaluation} className=\"mt-4\">\n            Save Evaluation Settings\n          </Button>\n        )}\n      </Card>\n\n      <Card>\n        <CardHeader><CardTitle>Interview Settings</CardTitle></CardHeader>\n        <div className=\"grid sm:grid-cols-2 gap-4\">\n          <NumberField\n            label=\"Default duration (minutes)\"\n            value={interview.defaultDurationMinutes}\n            onChange={(v) => setInterview((p) => ({ ...p, defaultDurationMinutes: v }))}\n          />\n          <NumberField\n            label=\"Questions per interview\"\n            value={interview.questionsPerInterview}\n            onChange={(v) => setInterview((p) => ({ ...p, questionsPerInterview: v }))}\n          />\n        </div>\n        {canEdit && (\n          <Button icon={Save} loading={savingInterview} onClick={saveInterview} className=\"mt-4\">\n            Save Interview Settings\n          </Button>\n        )}\n      </Card>\n    </div>\n  );\n}\n",
  "src/pages/admin/AdminAlertsPage.jsx": "import { useState, useEffect } from 'react';\nimport { Link } from 'react-router-dom';\nimport { TrendingDown, Clock3 } from 'lucide-react';\nimport Card from '../../components/Card';\nimport LoadingSpinner from '../../components/LoadingSpinner';\nimport ErrorMessage from '../../components/ErrorMessage';\nimport { adminAPI } from '../../services/adminApi';\n\nconst ICONS = { low_score: TrendingDown, inactive: Clock3 };\nconst SEVERITY_STYLE = {\n  high: 'border-red-500/30 hover:border-red-500/50',\n  medium: 'border-amber-500/30 hover:border-amber-500/50',\n  low: 'border-[#2a2a5a] hover:border-purple-500/40',\n};\n\nexport default function AdminAlertsPage() {\n  const [alerts, setAlerts] = useState(null);\n  const [loading, setLoading] = useState(true);\n  const [error, setError] = useState('');\n\n  useEffect(() => {\n    adminAPI.getAlerts()\n      .then((res) => setAlerts(res.data.alerts))\n      .catch((err) => setError(err.response?.data?.message || 'Could not load alerts'))\n      .finally(() => setLoading(false));\n  }, []);\n\n  if (loading) return <div className=\"h-64 flex items-center justify-center\"><LoadingSpinner size=\"lg\" /></div>;\n  if (error) return <ErrorMessage message={error} />;\n  if (!alerts) return null;\n\n  return (\n    <div className=\"space-y-6\">\n      <div>\n        <h1 className=\"text-2xl font-bold text-white\">Alerts</h1>\n        <p className=\"text-slate-400 mt-1 text-sm\">\n          {alerts.length} active — computed live from real score and login data, not stored or cached.\n        </p>\n      </div>\n\n      {alerts.length === 0 ? (\n        <Card><p className=\"text-sm text-slate-500 italic\">No active alerts right now.</p></Card>\n      ) : (\n        <div className=\"space-y-3\">\n          {alerts.map((a, i) => {\n            const Icon = ICONS[a.type] || TrendingDown;\n            return (\n              <Link\n                key={`${a.studentId}-${a.type}-${i}`}\n                to={`/admin/students?search=${encodeURIComponent(a.email)}`}\n                className={`block p-4 rounded-xl bg-[#141432] border transition-colors ${SEVERITY_STYLE[a.severity] || SEVERITY_STYLE.low}`}\n              >\n                <div className=\"flex items-start gap-3\">\n                  <div className=\"w-9 h-9 rounded-lg bg-white/5 flex items-center justify-center flex-shrink-0\">\n                    <Icon className=\"w-4 h-4 text-slate-300\" />\n                  </div>\n                  <div className=\"min-w-0\">\n                    <p className=\"text-white text-sm font-medium truncate\">{a.name}</p>\n                    <p className=\"text-slate-500 text-xs truncate\">{a.email}{a.college ? ` · ${a.college}` : ''}</p>\n                    <p className=\"text-slate-400 text-sm mt-1\">{a.detail}</p>\n                  </div>\n                </div>\n              </Link>\n            );\n          })}\n        </div>\n      )}\n    </div>\n  );\n}\n",
  "src/pages/admin/AdminAuditLogPage.jsx": "import { useState, useEffect } from 'react';\nimport { History } from 'lucide-react';\nimport Card from '../../components/Card';\nimport LoadingSpinner from '../../components/LoadingSpinner';\nimport ErrorMessage from '../../components/ErrorMessage';\nimport { adminAPI } from '../../services/adminApi';\n\nconst ACTION_LABELS = {\n  deactivate_student: 'Deactivated a student',\n  reactivate_student: 'Reactivated a student',\n  add_question: 'Added a question',\n  edit_question: 'Edited a question',\n  activate_question: 'Activated a question',\n  deactivate_question: 'Deactivated a question',\n  add_staff: 'Added a staff account',\n  deactivate_staff: 'Deactivated a staff account',\n  reactivate_staff: 'Reactivated a staff account',\n  update_evaluation_settings: 'Updated evaluation settings',\n  update_interview_settings: 'Updated interview settings',\n};\n\nexport default function AdminAuditLogPage() {\n  const [entries, setEntries] = useState(null);\n  const [loading, setLoading] = useState(true);\n  const [error, setError] = useState('');\n\n  useEffect(() => {\n    adminAPI.getAuditLog()\n      .then((res) => setEntries(res.data.entries))\n      .catch((err) => setError(err.response?.data?.message || 'Could not load audit log'))\n      .finally(() => setLoading(false));\n  }, []);\n\n  if (loading) return <div className=\"h-64 flex items-center justify-center\"><LoadingSpinner size=\"lg\" /></div>;\n  if (error) return <ErrorMessage message={error} />;\n  if (!entries) return null;\n\n  return (\n    <div className=\"space-y-6\">\n      <div>\n        <h1 className=\"text-2xl font-bold text-white\">Audit Log</h1>\n        <p className=\"text-slate-400 mt-1 text-sm\">Every admin/staff action that changes data, newest first. Admin-only.</p>\n      </div>\n\n      {entries.length === 0 ? (\n        <Card><p className=\"text-sm text-slate-500 italic\">No actions recorded yet.</p></Card>\n      ) : (\n        <Card hover={false} className=\"!p-0 overflow-hidden\">\n          <div className=\"divide-y divide-[#2a2a5a]\">\n            {entries.map((e) => (\n              <div key={e.id} className=\"p-4 flex items-start gap-3\">\n                <div className=\"w-8 h-8 rounded-lg bg-white/5 flex items-center justify-center flex-shrink-0\">\n                  <History className=\"w-4 h-4 text-slate-400\" />\n                </div>\n                <div className=\"min-w-0 flex-1\">\n                  <p className=\"text-white text-sm\">\n                    <span className=\"font-medium\">{e.admin_name || 'Unknown'}</span>{' '}\n                    {(ACTION_LABELS[e.action] || e.action).toLowerCase()}\n                  </p>\n                  {e.target && <p className=\"text-slate-500 text-xs truncate\">target: {e.target}</p>}\n                </div>\n                <p className=\"text-slate-500 text-xs flex-shrink-0\">{new Date(e.created_at).toLocaleString()}</p>\n              </div>\n            ))}\n          </div>\n        </Card>\n      )}\n    </div>\n  );\n}\n",
};

let created = 0, updated = 0, unchanged = 0;
for (const [relPath, content] of Object.entries(files)) {
  const full = path.join(process.cwd(), relPath);
  fs.mkdirSync(path.dirname(full), { recursive: true });
  const exists = fs.existsSync(full);
  const prev = exists ? fs.readFileSync(full, 'utf8') : null;
  if (prev === content) { unchanged++; console.log('  = unchanged  ' + relPath); continue; }
  fs.writeFileSync(full, content, 'utf8');
  if (exists) { updated++; console.log('  ~ updated    ' + relPath); }
  else { created++; console.log('  + created    ' + relPath); }
}
console.log(`\nDone. ${created} created, ${updated} updated, ${unchanged} unchanged.`);